import os
from typing import Dict, Any

def generate_markdown_report(data: Dict[str, Any], output_path: str = None) -> str:
    target = data.get("target", "Unknown")
    score = data.get("security_score", 0.0)
    posture = data.get("posture", "UNKNOWN")
    findings = data.get("findings", [])
    services = data.get("open_services", [])
    timestamp = data.get("scan_timestamp", "")

    md = f"""# 🛡️ Executive Security Assessment Report: `{target}`

**Generated by:** `cai-osint` Autonomous AI Security Auditor  
**Audit Timestamp:** `{timestamp}`  
**Overall Posture:** `{posture}`  
**Security Score:** `{score} / 10.0`  

---

## 📊 Executive Summary

| Target Host | Security Score | Posture Rating | Critical Issues | Total Open Ports |
| :--- | :--- | :--- | :--- | :--- |
| **{target}** | **{score} / 10.0** | **{posture}** | **{len([f for f in findings if f.get('severity') == 'CRITICAL'])}** | **{len(services)}** |

---

## 🚨 Security Findings & Vulnerabilities

"""
    if not findings:
        md += "✅ **No major perimeter vulnerabilities detected.** Target adheres to baseline security practices.\n\n"
    else:
        for f in findings:
            badge = "🔴 CRITICAL" if f['severity'] == 'CRITICAL' else "🟠 HIGH" if f['severity'] == 'HIGH' else "🟡 MEDIUM"
            md += f"""### {badge} - {f['title']}
* **Description:** {f['desc']}
* **Remediation Action:** `{f['remediation']}`

"""

    md += """---

## 🌐 Exposed Services & Open Ports

| Port | State | Identified Service | Service Banner |
| :--- | :--- | :--- | :--- |
"""
    if not services:
        md += "| - | None | All standard ports filtered/closed | - |\n"
    else:
        for s in services:
            md += f"| `{s['port']}` | `{s['state']}` | `{s['service']}` | `{s['banner']}` |\n"

    md += f"""
---

## 🔒 Actionable Remediation Checklist
- [ ] Review all open ports against company egress/ingress security policies.
- [ ] Ensure strict TLS 1.3 enforcement on port 443 with automated cert renewal.
- [ ] Place internal management and database ports behind a VPN or zero-trust tunnel.

*Report signed by `cai-osint` Engine (M4ST Ecosystem).*
"""

    if output_path:
        os.makedirs(os.path.dirname(output_path), exist_ok=True)
        with open(output_path, "w", encoding="utf-8") as f:
            f.write(md)

    return md
